import{_ as t,o,c as a,ao as r}from"./chunks/framework.8Wkhwg0B.js";const p=JSON.parse('{"title":"Parity with the oracle","description":"","frontmatter":{},"headers":[],"relativePath":"parity.md","filePath":"parity.md","lastUpdated":null}'),d={name:"parity.md"};function i(c,e,s,n,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="Parity-with-the-oracle" tabindex="-1">Parity with the oracle <a class="header-anchor" href="#Parity-with-the-oracle" aria-label="Permalink to &quot;Parity with the oracle {#Parity-with-the-oracle}&quot;">​</a></h1><p>QuantumEngine reproduces the Rust <code>quantum_engine</code>&#39;s reading of input files. The cases below are known to read differently. Each is listed with the input that shows it and what each program gives.</p><h2 id="Input-words" tabindex="-1">Input words <a class="header-anchor" href="#Input-words" aria-label="Permalink to &quot;Input words {#Input-words}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">input</th><th style="text-align:right;">QuantumEngine</th><th style="text-align:right;">oracle</th><th style="text-align:right;">cause</th></tr></thead><tbody><tr><td style="text-align:right;">a word holding the Kelvin sign U+212A, such as <code>bacK</code> for <code>back</code></td><td style="text-align:right;">not recognized (<code>nothing</code>)</td><td style="text-align:right;">recognized: Rust&#39;s <code>to_lowercase</code> maps U+212A to <code>k</code></td><td style="text-align:right;">the word lookups lowercase ASCII bytes only</td></tr><tr><td style="text-align:right;">the exact-exchange fraction of <code>libxc_hgga</code> or <code>libxc_hmgga</code> beyond the <code>Float64</code> range, such as <code>1e400</code></td><td style="text-align:right;">not a number (<code>method_word</code> returns <code>nothing</code>)</td><td style="text-align:right;"><code>inf</code> (<code>-1e400</code> gives <code>-inf</code>)</td><td style="text-align:right;">the fraction is read with Parsers.jl&#39;s <code>tryparse(Float64, ·)</code>, which rejects an out-of-range decimal as Julia&#39;s <code>tryparse</code> does; Rust&#39;s <code>f64</code> parser rounds it to an infinity</td></tr><tr><td style="text-align:right;">a keyword and its value separated by a Unicode white space other than space or tab, such as <code>charge</code> U+00A0 <code>1</code></td><td style="text-align:right;">one unknown word <code>charge</code> U+00A0 <code>1</code>: an error in strict mode, an <code>:unknown_keyword</code> warning in lenient mode, and the charge stays 0</td><td style="text-align:right;">two words: the charge is 1</td><td style="text-align:right;">the input lines are split on spaces and tabs only; the oracle&#39;s <code>split_whitespace</code> splits on every Unicode white space</td></tr></tbody></table><h2 id="Defaults" tabindex="-1">Defaults <a class="header-anchor" href="#Defaults" aria-label="Permalink to &quot;Defaults {#Defaults}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">input</th><th style="text-align:right;">QuantumEngine</th><th style="text-align:right;">oracle</th><th style="text-align:right;">cause</th></tr></thead><tbody><tr><td style="text-align:right;">an SMD solvation block without a probe radius</td><td style="text-align:right;"><code>probe_radius</code> = 0.40 Å = <code>0.7558904498503081</code> bohr</td><td style="text-align:right;"><code>0.7558903954315693</code> bohr, relative difference 7.2e-8</td><td style="text-align:right;">QuantumEngine converts with <code>Units.ANGSTROM_TO_BOHR</code> (CODATA 2018, 0.529177210903 Å per bohr); the oracle&#39;s SMD module divides by its own constant, 0.529177249 Å per bohr (<code>smd.rs</code>), which it also uses for a YAML <code>probe_radius</code> and for the solvent-accessible surface&#39;s 1.4 Å probe</td></tr></tbody></table><h2 id="The-parity-harness" tabindex="-1">The parity harness <a class="header-anchor" href="#The-parity-harness" aria-label="Permalink to &quot;The parity harness {#The-parity-harness}&quot;">​</a></h2><p>The test suite compares QuantumEngine with outputs of the oracle stored in the repository, so continuous integration needs no oracle binary. The harness lives in <code>test/oracle/</code>:</p><ul><li><p><code>harness.jl</code>, the test module <code>OracleHarness</code>: it locates and runs the oracle, reads its outputs, and reads the stored references and tolerances;</p></li><li><p><code>references.toml</code>: one <code>[case.&lt;name&gt;]</code> table per case, with the input text, the oracle file it is copied or derived from, the oracle command that runs it (<code>run</code> or <code>aimext</code>), the extractors and exports, the map from each compared quantity to its tolerance row, the extracted values and the SHA-256 of each captured file; and one <code>[fixture.&quot;&lt;path&gt;&quot;]</code> table per vendored fixture file, with the settings the oracle echoes for it;</p></li><li><p><code>tolerances.toml</code>: one row per class and quantity, with its value and its justification;</p></li><li><p><code>captured/</code>: the oracle&#39;s standard output of each case, its log for a <code>run</code> case and the files it exports, and in <code>captured/fixtures/</code> the standard output of each fixture file.</p></li></ul><h3 id="Capturing-the-oracle&#39;s-outputs" tabindex="-1">Capturing the oracle&#39;s outputs <a class="header-anchor" href="#Capturing-the-oracle&#39;s-outputs" aria-label="Permalink to &quot;Capturing the oracle&#39;s outputs {#Capturing-the-oracle&#39;s-outputs}&quot;">​</a></h3><p>The owner of a built oracle binary runs, from the repository root,</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>QUANTUM_ENGINE_ORACLE=&lt;binary&gt; QUANTUM_ENGINE_ORACLE_BASIS=&lt;basis_sets dir&gt; \\</span></span>
<span class="line"><span>QUANTUM_ENGINE_ORACLE_COMMIT=&lt;full hash&gt; \\</span></span>
<span class="line"><span>julia --project=QuantumEngine/test QuantumEngine/test/oracle/capture.jl [--fixtures] &lt;case&gt;...</span></span></code></pre></div><p>with the names of the cases to capture. For each case, <code>capture.jl</code> writes the case input as <code>&lt;case&gt;.inp</code> into a fresh temporary directory, links the basis directory there as <code>basis_sets</code> (the oracle resolves basis files relative to its working directory) and runs the oracle command that the case&#39;s <code>command</code> names in that directory: <code>quantum_engine run &lt;case&gt;.inp</code> for every case but <code>h2_qtaim</code>, which runs <code>quantum_engine aimext h2_qtaim.inp</code> (see below). It then writes <code>captured/&lt;case&gt;.stdout</code>, <code>captured/&lt;case&gt;.log</code> for a <code>run</code>, and the exported files, rewriting the <code>Reading input:</code> and <code>Logging to:</code> lines to name the case&#39;s files and dropping the lines that report elapsed time; it stops if an output still names the temporary directory, the home directory or the host name. Last it stores the extracted values, the files&#39; SHA-256 and the commit in <code>references.toml</code>. <code>--fixtures</code> also runs the six fixture files of the input tests unchanged and stores their echoed settings. A capture at a commit other than the stored one must name every case and <code>--fixtures</code>, so the file never mixes two oracle commits. The captured files are committed.</p><p>The stored outputs are those of the oracle at commit 4a78a1d235688c5af10ccd94be75d7292073ff8d (<code>meta.oracle_commit</code>), built from a clean checkout of that commit with <code>cargo build --release --no-default-features</code>: a headless build, without the GUI and GPU features (the GUI&#39;s dependency <code>objc2</code> 0.3.0-beta.3 does not compile with rustc 1.100.0), linked against Libxc 7.1.2 (shared library version 15) from Homebrew.</p><p>The case <code>o2_uhf_631g</code> sets <code>scf_convergence 1e-8</code>, the convergence of the oracle&#39;s reference value −149.545553662520; with the <code>1e-6</code> of its source file <code>examples/o2_triplet.inp</code> the oracle stops at −149.545553539349, 1.2e-7 Ha away and beyond the <code>uhf.energy</code> tolerance.</p><p>The live items (tag <code>:oracle</code>) run only when <code>QUANTUM_ENGINE_ORACLE</code> names the binary. They re-run every case and check that each compared quantity is still within its tolerance of <code>references.toml</code>.</p><h3 id="Adding-a-case" tabindex="-1">Adding a case <a class="header-anchor" href="#Adding-a-case" aria-label="Permalink to &quot;Adding a case {#Adding-a-case}&quot;">​</a></h3><ol><li><p>Add a <code>[case.&lt;name&gt;]</code> table to <code>references.toml</code>, with its <code>input</code>, <code>source</code>, <code>command</code> (<code>run</code>, or <code>aimext</code> for a critical-point report), <code>extract</code>, <code>exports</code> and <code>tolerance</code> map.</p></li><li><p>Capture it with <code>capture.jl</code>.</p></li><li><p>If the quantity is new, add an extractor to <code>OracleHarness</code>, written against the format string in the oracle source and citing it, with a test item that parses the captured file.</p></li><li><p>Write the comparison item, <code>@testitem &quot;&lt;step&gt;: &lt;case&gt; matches the oracle&quot; setup = [OracleHarness]</code>, which computes the QuantumEngine value and asserts <code>abs(value - reference(case, key)) ≤ tolerance(case, key)</code>.</p></li><li><p>Add the <code>tolerances.toml</code> rows the step&#39;s specification fixes, with their justification.</p></li></ol><p><code>tolerance(case, key)</code> throws for a quantity that has no entry in the case&#39;s map, or whose entry names a row that does not exist: a quantity without a row is never compared. It throws as well for a quantity in the case&#39;s <code>defects</code> table (see below).</p><h3 id="Traps-in-the-oracle&#39;s-output" tabindex="-1">Traps in the oracle&#39;s output <a class="header-anchor" href="#Traps-in-the-oracle&#39;s-output" aria-label="Permalink to &quot;Traps in the oracle&#39;s output {#Traps-in-the-oracle&#39;s-output}&quot;">​</a></h3><ul><li><p>For MP2 and CCSD runs the <code>Total Energy:</code> line is the SCF energy. The correlation energies are printed with <code>println!</code> by the post-SCF modules, so they appear only in the standard output, not in the log: <code>Total MP2 Correlation:</code> (<code>scf/mp2.rs:74</code>) and <code>FINAL CCSD CORRELATION:</code> (<code>scf/ccsd.rs:365</code>).</p></li><li><p>The <code>SCF converged … E =</code> line excludes the nuclear repulsion (<code>scf/scf_cycle.rs:591</code>); the harness reads the total energy only from the <code>Total Energy:</code> line, and the nuclear repulsion of a closed-shell run as the difference of the two.</p></li><li><p>The restricted <code>SCF iter</code> lines include the nuclear repulsion (<code>scf/scf_cycle.rs:500-503</code>); the unrestricted <code>UHF iter</code> lines do not (<code>scf/uhf.rs:260</code>). An unrestricted run prints no <code>SCF converged … E =</code> line.</p></li><li><p>The oracle reads <code>uhf</code> as its one Hartree-Fock method and chooses UHF by the multiplicity (<code>parser.rs:1127</code>).</p></li><li><p>The command line overrides the input&#39;s <code>verbosity</code> and <code>num_tddft_states</code> on every run, with its defaults 1 and 10 when the options are not given (<code>engine/config.rs:157-158</code>).</p></li><li><p><code>run qtaim</code> prints the QTAIM analysis to the log and writes no <code>.ext</code> report; the <code>.ext</code> report is written by the oracle&#39;s <code>aimext</code> command (<code>analysis/aim.rs:334-336</code>), so <code>h2_qtaim</code> is captured with <code>quantum_engine aimext h2_qtaim.inp</code>, run in the case&#39;s directory with <code>basis_sets</code> linked. Given an <code>.inp</code> file, <code>aimext</code> parses it, builds the basis, and loads <code>h2_qtaim.chk</code> from the input&#39;s directory if it exists; otherwise it runs the SCF itself and saves that checkpoint (<code>analysis/aim.rs:722-821</code>). It writes <code>h2_qtaim.ext</code> into the working directory and no log file (<code>main.rs:229-258</code>), so the case&#39;s captured files are <code>h2_qtaim.stdout</code> and <code>h2_qtaim.ext</code>. The input&#39;s <code>run qtaim</code> line has no effect on <code>aimext</code>.</p></li></ul><h3 id="Known-oracle-defects" tabindex="-1">Known oracle defects <a class="header-anchor" href="#Known-oracle-defects" aria-label="Permalink to &quot;Known oracle defects {#Known-oracle-defects}&quot;">​</a></h3><p>A captured quantity whose value is wrong is stored as captured and listed in its case&#39;s <code>defects</code> table with what is wrong; <code>tolerance</code> throws for it, so no comparison requires QuantumEngine to reproduce it.</p><table tabindex="0"><thead><tr><th style="text-align:right;">case</th><th style="text-align:right;">quantity</th><th style="text-align:right;">oracle</th><th style="text-align:right;">why it is wrong</th></tr></thead><tbody><tr><td style="text-align:right;"><code>h2_qtaim</code></td><td style="text-align:right;"><code>ext_report.n_nacp</code></td><td style="text-align:right;">4</td><td style="text-align:right;">H2 has two nuclei, and the report&#39;s own Poincaré–Hopf line reads <code>N_NACP - N_BCP + N_RCP - N_CCP = 3 [INCOMPLETE / NON-CONVERGED]</code> (<code>analysis/aim.rs:229-237</code>) instead of 1. The correct count is decided with the QTAIM analysis.</td></tr></tbody></table><p>The other <code>h2_qtaim</code> quantities (the counts of bond, ring and cage critical points and the bond critical point&#39;s ρ, Laplacian, <code>R_e</code>, <code>R_b</code>, <code>Delta_R</code> and ellipticity) are references.</p><h3 id="Tolerances" tabindex="-1">Tolerances <a class="header-anchor" href="#Tolerances" aria-label="Permalink to &quot;Tolerances {#Tolerances}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">row</th><th style="text-align:right;">value</th><th style="text-align:right;">justification</th></tr></thead><tbody><tr><td style="text-align:right;"><code>hf.energy</code></td><td style="text-align:right;">1e-9 Ha</td><td style="text-align:right;">AGENTS.md parity tolerance for HF energies; measured closed-shell oracle noise ~1e-12</td></tr><tr><td style="text-align:right;"><code>mp2.energy</code></td><td style="text-align:right;">1e-9 Ha</td><td style="text-align:right;">AGENTS.md parity tolerance for MP2 energies</td></tr><tr><td style="text-align:right;"><code>uhf.energy</code></td><td style="text-align:right;">1e-7 Ha</td><td style="text-align:right;">AGENTS.md parity tolerance for UHF energies</td></tr><tr><td style="text-align:right;"><code>geometry.angstrom</code></td><td style="text-align:right;">1e-4 Å</td><td style="text-align:right;">AGENTS.md parity tolerance for geometries</td></tr><tr><td style="text-align:right;"><code>frequency.cm1</code></td><td style="text-align:right;">1 cm⁻¹</td><td style="text-align:right;">AGENTS.md parity tolerance for frequencies</td></tr><tr><td style="text-align:right;"><code>nuclear_repulsion.energy</code></td><td style="text-align:right;">5e-13 Ha</td><td style="text-align:right;">half a unit in the last of the 12 decimals the <code>Total Energy:</code> and <code>SCF converged … E =</code> lines print</td></tr></tbody></table><p>The DFT rows (closed shell: the measured defect of the oracle&#39;s angular tables + 1e-8; open shell: the measured defect + 2e-6) are added with that measurement. Until then a DFT comparison throws for its missing row, as do the <code>ccsd.energy</code>, <code>gradient.norm</code> and <code>qtaim.*</code> rows that the steps implementing those quantities add.</p>`,28)])])}const g=t(d,[["render",i]]);export{p as __pageData,g as default};
